226→/**
227→ * Find active shares that cover a given folder, including ancestor shares.
228→ * A folder is "covered" if it or any of its ancestor folders is shared.
229→ *
230→ * Walks the ancestor chain and checks each folder's IPNS name against sent shares.
231→ *
232→ * @param folderIpnsName - IPNS name of the current folder
233→ * @param folders - Current folder tree from the folder store
234→ * @param currentFolderId - ID of the current folder in the tree
235→ * @returns Array of sent shares covering this folder (may be from ancestor)
236→ */
237→export async function findCoveringShares(
238→  folderIpnsName: string,
239→  folders: Record<string, FolderNode>,
240→  currentFolderId: string | null
241→): Promise<SentShare[]> {
242→  const shares = await ensureFreshSentShares();
243→  if (shares.length === 0) return [];
244→
245→  // Collect all IPNS names from this folder up to root
246→  const ipnsNames = new Set<string>();
247→  ipnsNames.add(folderIpnsName);
248→
249→  let walkId = currentFolderId;
250→  while (walkId) {
251→    const node = folders[walkId];
252→    if (!node) break;
253→    ipnsNames.add(node.ipnsName);
254→    walkId = node.parentId;
255→  }
256→
257→  return shares.filter((s) => ipnsNames.has(s.ipnsName));
258→}
