181→      }
182→    }
183→
184→    // Check not sharing with yourself
185→    const vaultKeypair = useAuthStore.getState().vaultKeypair;
186→    if (!vaultKeypair) {
187→      setError('vault keypair not available');
188→      return;
189→    }
190→
191→    const myPubKeyHex = '0x' + bytesToHex(vaultKeypair.publicKey);
192→    if (key.toLowerCase() === myPubKeyHex.toLowerCase()) {
193→      setError('cannot share with yourself');
194→      return;
195→    }
196→
197→    setIsSharing(true);
198→
199→    try {
200→      // Verify recipient is a registered user
201→      const lookup = await sharesControllerLookupUser({ publicKey: key });
202→      if (!lookup.exists) {
203→        setError('user not found');
204→        setIsSharing(false);
205→        return;
206→      }
207→    } catch {
208→      setError('lookup failed, please try again');
209→      setIsSharing(false);
210→      return;
211→    }
212→
213→    try {
214→      const recipientPubKeyBytes = hexToBytes(key.slice(2));
215→      const ownerPrivateKey = vaultKeypair.privateKey;
216→
217→      let encryptedKey: string;
218→      let childKeys: ChildKeyDto[] | undefined;
219→
220→      if (item.type === 'folder') {
221→        const folderEntry = item as FolderEntry;
222→
223→        // For folders shared from a parent, folderKey IS the folder's own key
224→        // (it's the folderKey passed as prop which is the parent's key --
225→        //  but the item is a FolderEntry child that has folderKeyEncrypted)
226→        // We need to use folderKeyEncrypted from the FolderEntry to get the actual folder key.
227→        // Wait -- the folderKey prop is the PARENT folder's key. The item's own key
228→        // is obtained by unwrapping folderKeyEncrypted from the FolderEntry.
229→        // Actually, looking at the plan more carefully:
230→        //   "For folders: folderKey is passed as prop"
231→        // But folderKey is the PARENT's key. For sharing a subfolder, we need the subfolder's key.
232→        // Let's check: if the item is a direct child folder, its folderKeyEncrypted
233→        // is wrapped with the owner's public key (ECIES). We unwrap it to get the folder's own key.
234→
235→        // Unwrap the folder's own key from its encrypted form
236→        const itemFolderKey = await unwrapKey(
237→          hexToBytes(folderEntry.folderKeyEncrypted),
238→          ownerPrivateKey
239→        );
240→
241→        try {
242→          // Wrap the folder key for the recipient
243→          const wrappedForRecipient = await wrapKey(itemFolderKey, recipientPubKeyBytes);
244→          encryptedKey = bytesToHex(wrappedForRecipient);
245→
246→          // Now traverse children and re-wrap descendant keys
247→          // First, resolve folder metadata to get children
248→          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
249→          if (resolved) {
250→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
251→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
252→            const encrypted = JSON.parse(encryptedJson);
253→            const metadata = await decryptFolderMetadata(encrypted, itemFolderKey);
254→
255→            setProgress({ current: 0, total: 0 });
256→
257→            childKeys = await collectChildKeys(
258→              metadata.children,
259→              itemFolderKey,
260→              ownerPrivateKey,
261→              recipientPubKeyBytes,
262→              (wrapped) => setProgress({ current: wrapped, total: 0 })
263→            );
264→          }
265→        } finally {
266→          itemFolderKey.fill(0);
267→        }
268→      } else {
269→        // File sharing: wrap parent folder key for recipient (needed to decrypt file metadata),
270→        // and re-wrap the file key as a child key entry
271→        const filePointer = item as FilePointer;
272→
273→        // encryptedKey = parent folder key wrapped for recipient
274→        const wrappedFolderKey = await wrapKey(folderKey, recipientPubKeyBytes);
275→        encryptedKey = bytesToHex(wrappedFolderKey);
276→
277→        // Re-wrap the file key for the recipient and store as child key
278→        const { metadata: fileMeta } = await resolveFileMetadata(
279→          filePointer.fileMetaIpnsName,
280→          folderKey
281→        );
282→        const reWrappedFileKey = await reWrapEncryptedKey(
283→          fileMeta.fileKeyEncrypted,
284→          ownerPrivateKey,
285→          recipientPubKeyBytes
286→        );
287→        childKeys = [
288→          { keyType: 'file' as const, itemId: filePointer.id, encryptedKey: reWrappedFileKey },
289→        ];
290→      }
291→
292→      // Create the share via API
293→      const itemType: CreateShareDtoItemType = item.type === 'folder' ? 'folder' : 'file';
294→      const result = await sharesControllerCreateShare({
295→        recipientPublicKey: key,
296→        itemType,
297→        ipnsName,
298→        itemName: item.name,
299→        encryptedKey,
300→        childKeys: childKeys && childKeys.length > 0 ? childKeys : undefined,
301→      });
302→
303→      // Update local recipients list and global store (for re-wrapping cache)
304→      const newShare = {
305→        shareId: result.shareId,
306→        recipientPublicKey: key,
307→        itemType: item.type as 'folder' | 'file',
308→        ipnsName,
309→        itemName: item.name,
310→        createdAt: new Date().toISOString(),
311→      };
312→      setRecipients((prev) => [...prev, newShare]);
313→      useShareStore.getState().addSentShare(newShare);
314→
315→      setSuccess(`shared with ${truncateKey(key)}`);
316→      setPubKeyInput('');
317→      setProgress(null);
318→    } catch (err) {
319→      console.error('Share creation failed:', err);
320→      const message = err instanceof Error ? err.message : 'share creation failed';
321→      setError(message);
322→    } finally {
323→      setIsSharing(false);
324→      setProgress(null);
325→    }
326→  }, [pubKeyInput, item, folderKey, ipnsName, parentFolderId]);
327→
328→  const handleRevoke = useCallback(async (shareId: string) => {
329→    setRevokingId(shareId);
330→    setConfirmRevokeId(null);
331→    try {
332→      await sharesControllerRevokeShare(shareId);
333→      setRecipients((prev) => prev.filter((r) => r.shareId !== shareId));
334→      useShareStore.getState().removeSentShare(shareId);
335→    } catch (err) {
336→      console.error('Revoke failed:', err);
337→      setError('revoke failed');
338→    } finally {
339→      setRevokingId(null);
340→    }
341→  }, []);
342→
343→  const handleKeyDown = useCallback(
344→    (e: React.KeyboardEvent) => {
345→      if (e.key === 'Enter' && !isSharing) {
346→        handleShare();
347→      }
348→    },
349→    [handleShare, isSharing]
350→  );
351→
352→  const itemDisplayName = item.type === 'folder' ? `${item.name}/` : item.name;
353→  const title = `SHARE: ${itemDisplayName}`;
354→
355→  return (
356→    <Modal open={isOpen} onClose={onClose} title={title} className="share-dialog-backdrop">
357→      <div className="share-dialog">
358→        {/* Tab bar */}
359→        <div className="share-tab-bar" role="tablist" aria-label="Share method">
360→          <button
361→            ref={directTabRef}
362→            type="button"
363→            role="tab"
364→            id="share-tab-direct"
365→            aria-selected={activeTab === 'direct'}
366→            aria-controls="share-panel-direct"
367→            tabIndex={activeTab === 'direct' ? 0 : -1}
368→            className={`share-tab${activeTab === 'direct' ? ' share-tab--active' : ''}`}
369→            onClick={() => setActiveTab('direct')}
370→            onKeyDown={(e) => {
371→              if (e.key === 'ArrowRight') {
372→                e.preventDefault();
373→                setActiveTab('invite');
374→                inviteTabRef.current?.focus();
375→              }
376→            }}
377→          >
378→            {'DIRECT SHARE'}
379→          </button>
380→          <button
381→            ref={inviteTabRef}
382→            type="button"
383→            role="tab"
384→            id="share-tab-invite"
385→            aria-selected={activeTab === 'invite'}
386→            aria-controls="share-panel-invite"
387→            tabIndex={activeTab === 'invite' ? 0 : -1}
388→            className={`share-tab${activeTab === 'invite' ? ' share-tab--active' : ''}`}
389→            onClick={() => setActiveTab('invite')}
390→            onKeyDown={(e) => {
391→              if (e.key === 'ArrowLeft') {
392→                e.preventDefault();
393→                setActiveTab('direct');
394→                directTabRef.current?.focus();
395→              }
396→            }}
397→          >
398→            {'INVITE LINK'}
399→          </button>
400→        </div>
401→
402→        {/* Direct Share tab panel */}
403→        {activeTab === 'direct' && (
404→          <div role="tabpanel" id="share-panel-direct" aria-labelledby="share-tab-direct">
405→            {/* Input section */}
406→            <div className="share-input-section">
407→              <label className="share-input-label" htmlFor="share-pubkey-input">
408→                {'// paste recipient public key'}
409→              </label>
410→              <div className="share-input-row">
411→                <input
412→                  ref={inputRef}
413→                  id="share-pubkey-input"
414→                  type="text"
415→                  className={`share-input${error ? ' share-input--error' : ''}`}
416→                  placeholder="0x04..."
417→                  value={pubKeyInput}
418→                  onChange={(e) => {
419→                    setPubKeyInput(e.target.value);
420→                    setError(null);
421→                    setSuccess(null);
422→                  }}
423→                  onKeyDown={handleKeyDown}
424→                  disabled={isSharing}
425→                  autoComplete="off"
426→                  spellCheck={false}
427→                />
428→                <button
429→                  type="button"
430→                  className="share-submit-btn"
431→                  onClick={handleShare}
432→                  disabled={isSharing || !pubKeyInput.trim()}
433→                >
434→                  {isSharing ? '...' : '--share'}
435→                </button>
436→              </div>
437→
438→              {/* Error message */}
439→              {error && (
440→                <div className="share-error" role="alert">
441→                  {'> '}
442→                  {error}
443→                </div>
444→              )}
445→
446→              {/* Success message */}
447→              {success && (
448→                <div className="share-success" role="status">
449→                  {'> '}
450→                  {success}
451→                </div>
452→              )}
453→
454→              {/* Progress indicator for folder sharing */}
455→              {progress && (
456→                <div className="share-progress" role="status" aria-live="polite">
457→                  {'> '}re-wrapping keys... {progress.current}
458→                </div>
459→              )}
460→            </div>
461→
462→            {/* Recipients section */}
463→            <div className="share-recipients-section">
464→              <div className="share-recipients-header">{'// recipients'}</div>
465→
466→              {recipientsLoading || !recipientsFetched ? (
467→                <div className="share-recipients-loading">loading...</div>
468→              ) : recipients.length === 0 ? (
469→                <div className="share-recipients-empty">no recipients yet</div>
470→              ) : (
471→                <div className="share-recipients-list">
472→                  {recipients.map((recipient) => (
473→                    <div key={recipient.shareId} className="share-recipient">
474→                      <span className="share-recipient-key">
475→                        {truncateKey(recipient.recipientPublicKey)}
476→                      </span>
477→
478→                      {confirmRevokeId === recipient.shareId ? (
479→                        <div className="share-revoke-confirm">
480→                          <span className="share-revoke-confirm-text">{'confirm?'}</span>
481→                          <button
482→                            type="button"
483→                            className="share-revoke-confirm-btn share-revoke-confirm-btn--yes"
484→                            onClick={() => handleRevoke(recipient.shareId)}
485→                            disabled={revokingId === recipient.shareId}
486→                            aria-label="Confirm revoke"
487→                          >
488→                            {revokingId === recipient.shareId ? '...' : '[y]'}
489→                          </button>
490→                          <button
491→                            type="button"
492→                            className="share-revoke-confirm-btn share-revoke-confirm-btn--no"
493→                            onClick={() => setConfirmRevokeId(null)}
494→                            aria-label="Cancel revoke"
495→                          >
496→                            [n]
497→                          </button>
498→                        </div>
499→                      ) : (
500→                        <button
501→                          type="button"
502→                          className="share-revoke-btn"
503→                          onClick={() => setConfirmRevokeId(recipient.shareId)}
504→                          disabled={revokingId !== null}
505→                          aria-label={`Revoke share for ${truncateKey(recipient.recipientPublicKey)}`}
506→                        >
507→                          --revoke
508→                        </button>
509→                      )}
510→                    </div>
511→                  ))}
512→                </div>
513→              )}
514→            </div>
515→          </div>
516→        )}
517→
518→        {/* Invite Link tab panel */}
519→        {activeTab === 'invite' && (
520→          <InviteLinkTab
521→            item={item}
522→            folderKey={folderKey}
523→            ipnsName={ipnsName}
524→            parentFolderId={parentFolderId}
525→            isOpen={isOpen && activeTab === 'invite'}
526→          />
527→        )}
528→      </div>
529→    </Modal>
530→  );
531→}
