116→  private async reWrapNewItems(
117→    folderIpnsName: string,
118→    items: Array<{ keyType: 'file' | 'folder'; itemId: string; plaintextKey: Uint8Array }>
119→  ): Promise<void> {
120→    const callbacks = this.config.shareCallbacks;
121→    if (!callbacks) return;
