 31→/**
 32→ * Fetch and decrypt folder metadata from IPFS.
 33→ *
 34→ * @param cid - IPFS CID of the encrypted metadata blob
 35→ * @param folderKey - Decrypted AES-256 folder key
 36→ * @param ctx - SDK context for IPFS access
 37→ * @returns Decrypted folder metadata (v2)
 38→ */
 39→export async function fetchAndDecryptMetadata(
 40→  cid: string,
 41→  folderKey: Uint8Array,
 42→  ctx: SdkContext
 43→): Promise<FolderMetadata> {
 44→  return withPerf('folder:fetch-decrypt', async () => {
 45→    const encryptedBytes = await fetchFromIpfs(ctx, cid);
 46→
 47→    // All folder metadata (including root) is v1 JSON {iv, data}.
 48→    // v2 blob format is only for the vault key blob (separate IPNS name).
 49→    const encryptedJson = new TextDecoder().decode(encryptedBytes);
 50→    const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
 51→    return decryptFolderMetadata(encrypted, folderKey);
 52→  });
 53→}
 54→
 55→/**
 56→ * Load a folder's metadata from IPNS.
 57→ *
 58→ * Resolves the folder's IPNS name to get the current metadata CID,
 59→ * fetches and decrypts the metadata.
 60→ *
 61→ * @returns Decrypted folder metadata, sequence number, and CID, or null if IPNS not found
 62→ */
 63→export async function loadFolderMetadata(params: {
 64→  ipnsName: string;
 65→  folderKey: Uint8Array;
 66→  ctx: SdkContext;
 67→}): Promise<{
 68→  metadata: FolderMetadata;
 69→  sequenceNumber: bigint;
 70→  cid: string;
 71→} | null> {
 72→  return withPerf('folder:load', async () => {
 73→    const resolved = await resolveIpnsRecord(params.ipnsName, params.ctx);
 74→    if (!resolved) return null;
 75→
 76→    const metadata = await fetchAndDecryptMetadata(resolved.cid, params.folderKey, params.ctx);
 77→
 78→    return {
 79→      metadata,
 80→      sequenceNumber: resolved.sequenceNumber,
 81→      cid: resolved.cid,
 82→    };
 83→  });
 84→}
