 86→/**
 87→ * Create a new subfolder with generated keys.
 88→ *
 89→ * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 90→ * wraps them with the user's public key for storage.
 91→ *
 92→ * @returns Created folder entry and decrypted keys
 93→ */
 94→export async function createSubfolder(params: {
 95→  name: string;
 96→  userPublicKey: Uint8Array;
 97→  teeKeys?: TeeKeys;
 98→}): Promise<{
 99→  folder: FolderEntry;
100→  ipnsPrivateKey: Uint8Array;
101→  folderKey: Uint8Array;
102→  encryptedIpnsPrivateKey?: string;
103→  keyEpoch?: number;
104→}> {
105→  // 1. Generate Ed25519 keypair for folder IPNS
106→  const ipnsKeypair = await generateEd25519Keypair();
107→  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
108→
109→  // 2. Generate random AES-256 folder key
110→  const folderKey = generateRandomBytes(32);
111→
112→  // 3. Wrap keys with user's public key (ECIES encryption)
113→  const ipnsPrivateKeyEncrypted = bytesToHex(
114→    await wrapKey(ipnsKeypair.privateKey, params.userPublicKey)
115→  );
116→  const folderKeyEncrypted = bytesToHex(await wrapKey(folderKey, params.userPublicKey));
117→
118→  // 4. TEE-02: Encrypt IPNS private key with TEE public key for republishing.
119→  //    Wrap remaining steps in try/catch to zero key material on error.
120→  //    On success the caller receives the keys, so we only zero on failure.
121→  try {
122→    let encryptedIpnsPrivateKey: string | undefined;
123→    let keyEpoch: number | undefined;
124→
125→    if (params.teeKeys?.currentPublicKey) {
126→      const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
127→      const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
128→      encryptedIpnsPrivateKey = bytesToHex(encryptedKey);
129→      keyEpoch = params.teeKeys.currentEpoch;
130→    }
131→
132→    // 5. Create folder entry for parent's metadata
133→    const now = Date.now();
134→    const folder: FolderEntry = {
135→      type: 'folder',
136→      id: crypto.randomUUID(),
137→      name: params.name,
138→      ipnsName,
139→      ipnsPrivateKeyEncrypted,
140→      folderKeyEncrypted,
141→      createdAt: now,
142→      modifiedAt: now,
143→    };
144→
145→    return {
146→      folder,
147→      ipnsPrivateKey: ipnsKeypair.privateKey,
148→      folderKey,
149→      encryptedIpnsPrivateKey,
150→      keyEpoch,
151→    };
152→  } catch (error) {
153→    ipnsKeypair.privateKey.fill(0);
154→    folderKey.fill(0);
155→    throw error;
156→  }
157→}
