159→/**
160→ * Update folder metadata and publish to IPNS.
161→ *
162→ * Encrypts the metadata with the folder key, uploads to IPFS,
163→ * and publishes an updated IPNS record pointing to the new CID.
164→ *
165→ * @returns New CID and sequence number
166→ */
167→export async function updateFolderMetadataAndPublish(params: {
168→  children: FolderChild[];
169→  folderKey: Uint8Array;
170→  ipnsPrivateKey: Uint8Array;
171→  ipnsName: string;
172→  sequenceNumber: bigint;
173→  ctx: SdkContext;
174→  encryptedIpnsPrivateKey?: string;
175→  keyEpoch?: number;
176→}): Promise<{ cid: string; newSequenceNumber: bigint }> {
177→  return withPerf('folder:update-publish', async () => {
178→    // 1. Create v2 folder metadata
179→    const metadata: FolderMetadata = {
180→      version: 'v2',
181→      children: params.children,
182→    };
183→
184→    // 2. Encrypt metadata with folder key
185→    const encrypted = await encryptFolderMetadata(metadata, params.folderKey);
186→
187→    // 3. Upload to IPFS via backend relay
188→    const jsonStr = JSON.stringify(encrypted);
189→    const encryptedBytes = new TextEncoder().encode(jsonStr);
190→    const { cid } = await addToIpfs(params.ctx, encryptedBytes);
191→
192→    // 4. Publish IPNS record with conflict retry
193→    //    On 409, resolve current seq from IPNS and retry once
194→    let currentSeq = params.sequenceNumber;
195→
196→    for (let attempt = 0; attempt < 2; attempt++) {
197→      const newSeq = currentSeq + 1n;
198→      try {
199→        await createAndPublishIpnsRecord({
200→          ipnsPrivateKey: params.ipnsPrivateKey,
201→          ipnsName: params.ipnsName,
202→          metadataCid: cid,
203→          sequenceNumber: newSeq,
204→          encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
205→          keyEpoch: params.keyEpoch,
206→          expectedSequenceNumber: currentSeq.toString(),
207→          ctx: params.ctx,
208→        });
209→        return { cid, newSequenceNumber: newSeq };
210→      } catch (err) {
211→        const is409 =
212→          (err as Error & { status?: number }).status === 409 ||
213→          (err as Error & { response?: { status?: number } }).response?.status === 409;
214→        if (!is409 || attempt > 0) throw err;
215→
216→        // Re-sync: resolve current seq from IPNS
217→        const resolved = await resolveIpnsRecord(params.ipnsName, params.ctx);
218→        if (resolved) {
219→          currentSeq = resolved.sequenceNumber;
220→        } else {
221→          throw err; // Can't resolve → give up
222→        }
223→      }
224→    }
225→
226→    // Should not reach here, but TypeScript needs it
227→    throw new Error('Publish failed after retry');
228→  });
229→}
