259→/**
260→ * Remove a child entry (folder or file) from folder metadata.
261→ *
262→ * Pure metadata operation: returns updated children array and the removed item.
263→ */
264→export function deleteFromFolder(params: { children: FolderChild[]; childId: string }): {
265→  updatedChildren: FolderChild[];
266→  removedItem: FolderChild;
267→} {
268→  const index = params.children.findIndex((c) => c.id === params.childId);
269→  if (index === -1) throw new Error('Item not found');
270→
271→  const removedItem = params.children[index];
272→  const updatedChildren = params.children.filter((c) => c.id !== params.childId);
273→
274→  return { updatedChildren, removedItem };
275→}
