295→    id: params.fileId,
296→    name: params.fileName,
297→    fileMetaIpnsName: params.fileMetaIpnsName,
298→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
299→    createdAt: now,
