11→/**
12→ * React hook for file upload with encryption, progress tracking, and quota management.
13→ *
14→ * Currently uses upload.service.ts for the upload flow. The SDK client is used
15→ * for post-upload operations (adding files to folders) via useFileOperations.
16→ */
17→export function useFileUpload() {
18→  const { status, progress, currentFile, totalFiles, completedFiles, error, cancel, reset } =
19→    useUploadStore();
20→
21→  const { usedBytes, limitBytes, remainingBytes, canUpload, fetchQuota } = useQuotaStore();
22→  const { vaultKeypair } = useAuthStore();
23→
24→  const upload = useCallback(
25→    async (files: File[]): Promise<UploadedFile[]> => {
26→      if (!vaultKeypair) {
27→        throw new Error('No keypair available - please log in again');
28→      }
29→
30→      // Refresh quota before upload
31→      await fetchQuota();
32→
33→      return uploadFiles(files, vaultKeypair.publicKey);
34→    },
35→    [vaultKeypair, fetchQuota]
36→  );
37→
38→  return {
39→    // State
40→    status,
41→    progress,
42→    currentFile,
43→    totalFiles,
44→    completedFiles,
45→    error,
46→    isUploading: status === 'encrypting' || status === 'uploading' || status === 'registering',
47→
48→    // Quota
49→    usedBytes,
50→    limitBytes,
51→    remainingBytes,
52→    canUpload,
53→
54→    // Actions
55→    upload,
56→    cancel,
57→    reset,
58→  };
