330→   *
331→   * NOTE: No conflict detection here -- handleUpdateFile publishes only the
332→   * per-file IPNS record. Folder metadata is NOT touched, so no 409 is possible.
333→   *
334→   * @param parentId - Parent folder ID ('root' or folder UUID)
335→   * @param fileData - New file data after re-encryption
336→   * @returns Resolves when the update is complete
337→   */
338→  const handleUpdateFile = useCallback(
339→    async (
340→      parentId: string,
341→      fileData: {
342→        fileId: string;
343→        newCid: string;
344→        newFileKeyEncrypted: string;
345→        newFileIv: string;
346→        newSize: number;
347→        newEncryptionMode?: 'GCM' | 'CTR';
348→        forceVersion?: boolean; // true for web re-upload, false/undefined for text editor
349→      }
350→    ): Promise<void> => {
351→      setState({ isLoading: true, error: null });
352→      try {
353→        const folders = useFolderStore.getState().folders;
354→        const vault = useVaultStore.getState();
355→        const auth = useAuthStore.getState();
356→
357→        if (!auth.vaultKeypair) {
358→          throw new Error('No ECIES keypair available - please log in again');
359→        }
360→
361→        // Get parent folder state
362→        const parentFolder =
363→          parentId === 'root' ? getRootFolderState(vault, folders) : folders[parentId];
364→
365→        if (!parentFolder) {
366→          throw new Error('Parent folder not found or vault not initialized');
367→        }
368→
369→        // 1. Find the FilePointer in parent's children
370→        const filePointer = parentFolder.children.find(
371→          (c) => c.type === 'file' && c.id === fileData.fileId
372→        ) as FilePointer | undefined;
373→
374→        if (!filePointer) {
375→          throw new Error('File not found in folder');
376→        }
377→
378→        // 2. Resolve current file metadata from IPNS
379→        const { metadata: currentMetadata } = await resolveFileMetadata(
380→          filePointer.fileMetaIpnsName,
381→          parentFolder.folderKey
382→        );
383→
384→        // 3. Decrypt the file IPNS private key from FilePointer (or HKDF fallback)
385→        const { privateKey: fileIpnsPrivateKey, migratedIpnsPrivateKeyEncrypted } =
386→          await getFileIpnsPrivateKey(
387→            filePointer,
388→            auth.vaultKeypair.privateKey,
389→            auth.vaultKeypair.publicKey
390→          );
391→
392→        // 4. Determine whether to create a version entry
393→        const createVersion = shouldCreateVersion(currentMetadata, fileData.forceVersion ?? false);
394→
395→        let ipnsRecord: FileIpnsRecordPayload;
396→        let prunedCids: string[];
397→        try {
398→          // 5. Update file metadata and publish new IPNS record
399→          ({ ipnsRecord, prunedCids } = await updateFileMetadata({
400→            fileIpnsPrivateKey,
401→            fileMetaIpnsName: filePointer.fileMetaIpnsName,
402→            folderKey: parentFolder.folderKey,
403→            currentMetadata,
404→            updates: {
405→              cid: fileData.newCid,
406→              fileKeyEncrypted: fileData.newFileKeyEncrypted,
407→              fileIv: fileData.newFileIv,
408→              size: fileData.newSize,
409→              ...(fileData.newEncryptionMode ? { encryptionMode: fileData.newEncryptionMode } : {}),
410→            },
411→            createVersion,
412→          }));
413→        } finally {
414→          fileIpnsPrivateKey.fill(0);
415→        }
416→
417→        // 6. Publish only the file IPNS record (folder metadata untouched!)
418→        await folderService.replaceFileInFolder({
419→          fileId: fileData.fileId,
420→          fileIpnsRecord: ipnsRecord,
421→          parentFolderState: parentFolder,
422→        });
423→
424→        // 7. Update local state -- touch modifiedAt and persist migrated IPNS key if applicable
425→        const updatedChildren = parentFolder.children.map((child) => {
426→          if (child.type === 'file' && child.id === fileData.fileId) {
427→            return {
428→              ...child,
429→              modifiedAt: Date.now(),
430→              ...(migratedIpnsPrivateKeyEncrypted
431→                ? { ipnsPrivateKeyEncrypted: migratedIpnsPrivateKeyEncrypted }
432→                : {}),
433→            };
434→          }
435→          return child;
436→        });
437→
438→        const store = useFolderStore.getState();
439→        store.updateFolderChildren(parentId, updatedChildren);
440→
441→        // 7b. Lazy migration: persist wrapped IPNS key to folder metadata on IPFS
442→        if (migratedIpnsPrivateKeyEncrypted) {
443→          folderService
444→            .updateFolderMetadata({
445→              folderId: parentFolder.id,
446→              children: updatedChildren,
447→              folderKey: parentFolder.folderKey,
448→              ipnsPrivateKey: parentFolder.ipnsPrivateKey,
449→              ipnsName: parentFolder.ipnsName,
450→              sequenceNumber: parentFolder.sequenceNumber,
451→            })
452→            .then(({ newSequenceNumber }) => {
453→              useFolderStore.getState().updateFolderSequence(parentId, newSequenceNumber);
454→            })
455→            .catch((err) => {
456→              console.warn('Lazy IPNS key migration: folder re-publish failed, will retry:', err);
457→            });
458→        }
459→
460→        // 8. Only unpin CIDs of pruned versions (excess beyond max 10)
461→        // Old CIDs stay pinned as version history (VER-01)
462→        for (const prunedCid of prunedCids) {
463→          unpinFromIpfs(prunedCid).catch(() => {});
464→        }
465→
466→        // Refresh quota
467→        useQuotaStore.getState().fetchQuota();
468→
469→        setState({ isLoading: false, error: null });
470→      } catch (err) {
